'use strict';

// MODULES //

var resolve = require( 'path' ).resolve;
var tape = require( 'tape' );
var PI = require( '@stdlib/constants/float32/pi' );
var PINF = require( '@stdlib/constants/float32/pinf' );
var NINF = require( '@stdlib/constants/float32/ninf' );
var isnanf = require( '@stdlib/math/base/assert/is-nanf' );
var isNegativeZerof = require( '@stdlib/math/base/assert/is-negative-zerof' );
var isPositiveZerof = require( '@stdlib/math/base/assert/is-positive-zerof' );
var f32 = require( '@stdlib/number/float64/base/to-float32' );
var tryRequire = require( '@stdlib/utils/try-require' );


// VARIABLES //

var truncsdf = tryRequire( resolve( __dirname, './../lib/native.js' ) );
var opts = {
	'skip': ( truncsdf instanceof Error )
};


// TESTS //

tape( 'main export is a function', opts, function test( t ) {
	t.ok( true, __filename );
	t.strictEqual( typeof truncsdf, 'function', 'main export is a function' );
	t.end();
});

tape( 'the function returns `NaN` if provided `NaN`', opts, function test( t ) {
	var v;

	v = truncsdf( NaN, 2, 10 );
	t.strictEqual( isnanf( v ), true, 'returns expected value' );

	t.end();
});

tape( 'the function returns `NaN` if provided `n < 1`', opts, function test( t ) {
	var v;

	v = truncsdf( PI, 0, 10 );
	t.strictEqual( isnanf( v ), true, 'returns expected value' );

	v = truncsdf( PI, -1, 10 );
	t.strictEqual( isnanf( v ), true, 'returns expected value' );

	t.end();
});

tape( 'the function returns `NaN` if provided `b <= 0`', opts, function test( t ) {
	var v;

	v = truncsdf( PI, 2, 0 );
	t.strictEqual( isnanf( v ), true, 'returns expected value' );

	v = truncsdf( PI, 2, -1 );
	t.strictEqual( isnanf( v ), true, 'returns expected value' );

	t.end();
});

tape( 'the function returns `+infinity` if provided `+infinity`', opts, function test( t ) {
	var v = truncsdf( PINF, 5, 10 );
	t.strictEqual( v, PINF, 'returns expected value' );
	t.end();
});

tape( 'the function returns `-infinity` if provided `-infinity`', opts, function test( t ) {
	var v = truncsdf( NINF, 3, 10 );
	t.strictEqual( v, NINF, 'returns expected value' );
	t.end();
});

tape( 'the function returns `-0` if provided `-0`', opts, function test( t ) {
	var v;

	v = truncsdf( -0.0, 1, 10 );
	t.strictEqual( isNegativeZerof( v ), true, 'returns expected value' );

	v = truncsdf( -0.0, 2, 10 );
	t.strictEqual( isNegativeZerof( v ), true, 'returns expected value' );

	t.end();
});

tape( 'the function returns `+0` if provided `+0`', opts, function test( t ) {
	var v;

	v = truncsdf( 0.0, 1, 10 );
	t.strictEqual( isPositiveZerof( v ), true, 'returns expected value' );

	v = truncsdf( +0.0, 2, 10 );
	t.strictEqual( isPositiveZerof( v ), true, 'returns expected value' );

	t.end();
});

tape( 'the function supports rounding a numeric value with a specified number of significant figures (base 10)', opts, function test( t ) {
	t.strictEqual( truncsdf( PI, 1, 10 ), 3.0, 'returns expected value' );
	t.strictEqual( truncsdf( -PI, 1, 10 ), -3.0, 'returns expected value' );
	t.strictEqual( truncsdf( PI, 2, 10 ), 3.0999999046325684, 'returns expected value' );
	t.strictEqual( truncsdf( -PI, 2, 10 ), -3.0999999046325684, 'returns expected value' );
	t.strictEqual( truncsdf( PI, 3, 10 ), 3.140000104904175, 'returns expected value' );
	t.strictEqual( truncsdf( -PI, 3, 10 ), -3.140000104904175, 'returns expected value' );
	t.strictEqual( truncsdf( PI, 4, 10 ), 3.1410000324249268, 'returns expected value' );
	t.strictEqual( truncsdf( 12368.0, 1, 10 ), 10000.0, 'returns expected value' );
	t.strictEqual( truncsdf( 12368.0, 2, 10 ), 12000.0, 'returns expected value' );
	t.strictEqual( truncsdf( -12368.0, 2, 10 ), -12000.0, 'returns expected value' );
	t.strictEqual( truncsdf( 12368.0, 3, 10 ), 12300.0, 'returns expected value' );
	t.strictEqual( truncsdf( -12368.0, 3, 10 ), -12300.0, 'returns expected value' );
	t.strictEqual( truncsdf( 999999.0, 3, 10 ), 999000.0, 'returns expected value' );
	t.strictEqual( truncsdf( 0.5, 1, 10 ), 0.5, 'returns expected value' );
	t.strictEqual( truncsdf( 96.0, 1, 10 ), 90.0, 'returns expected value' );
	t.end();
});

tape( 'the function supports rounding a numeric value with a specified number of significant figures (base 2)', opts, function test( t ) {
	t.strictEqual( truncsdf( 0.0313, 1, 2 ), 0.03125, 'returns expected value' );
	t.strictEqual( truncsdf( 0.0313, 2, 2 ), 0.03125, 'returns expected value' );
	t.strictEqual( truncsdf( 0.0313, 5, 2 ), 0.03125, 'returns expected value' );
	t.strictEqual( truncsdf( 0.0313, 9, 2 ), 0.03125, 'returns expected value' );
	t.strictEqual( truncsdf( 0.0313, 10, 2 ), 0.03125, 'returns expected value' );
	t.strictEqual( truncsdf( 0.0313, 11, 2 ), 0.031280517578125, 'returns expected value' );
	t.end();
});

tape( 'the function supports rounding a numeric value with a specified number of significant figures using an arbitrary base', opts, function test( t ) {
	t.strictEqual( truncsdf( 0.0313, 1, 16 ), 0.03125, 'returns expected value' );
	t.strictEqual( truncsdf( 0.0313, 5, 16 ), 0.03129994869232178, 'returns expected value' );
	t.strictEqual( truncsdf( 255.0, 1, 16 ), 240.0, 'returns expected value' );
	t.strictEqual( truncsdf( 255.0, 2, 16 ), 255.0, 'returns expected value' );
	t.end();
});

tape( 'if the function encounters overflow, the function returns the input value', opts, function test( t ) {
	var x;
	var v;

	x = 3.1415927410125732;
	v = truncsdf( x, 1000, 10 );
	t.strictEqual( v, x, 'returns expected value' );

	x = -3.1415927410125732;
	v = truncsdf( x, 1000, 10 );
	t.strictEqual( v, x, 'returns expected value' );

	x = 16777216.0;
	v = truncsdf( x, 320, 10 );
	t.strictEqual( v, x, 'returns expected value' );

	x = -16777216.0;
	v = truncsdf( x, 320, 10 );
	t.strictEqual( v, x, 'returns expected value' );

	// Subnormal values for which the required scale factor overflows:
	x = f32( 1.0e-42 );
	v = truncsdf( x, 2, 10 );
	t.strictEqual( v, x, 'returns expected value' );

	x = f32( 1.0e-40 );
	v = truncsdf( x, 2, 2 );
	t.strictEqual( v, x, 'returns expected value' );

	x = f32( 1.401298464324817e-45 );
	v = truncsdf( x, 1, 10 );
	t.strictEqual( v, x, 'returns expected value' );

	t.end();
});
